let reflectionShareDraft=null,reflectionShareGeneration=0,reflectionShareLock=null;
function resetReflectionShareClient(){reflectionShareDraft=null;reflectionShareGeneration++;if(reflectionShareLock){reflectionShareLock=null;lockShared(false)}}
function reflectionSharingPanel(p){const r=p?.reflections?.[uid];if(!['s1','s2'].includes(uid)||!p.members.includes(uid)||!r?.text||!Number.isSafeInteger(r.version)||r.version<1||!Number.isFinite(Date.parse(r.time)))return '';return `<section class="notice"><h4>Share my submitted reflection</h4><p>Share now or later, without waiting for mentor review. Sharing is optional and does not publish on the KCC website.</p>${btn('Share reflection',esc('openReflectionShare('+JSON.stringify(p.id)+')'))} ${btn('Manage share links','managePortfolioShares()')}</section>`}
function reflectionShareCurrent(c){return c.actor===uid&&c.actor===sharedActor&&c.revision===sharedRevision&&c.generation===reflectionShareGeneration}
function openReflectionShare(projectId){if(!sharedReady||sharedBusy||uid!==sharedActor)return;const p=db.projects.find(p=>p.id===projectId);if(!p||!reflectionSharingPanel(p))return toast('Submit your own reflection before sharing.');resetReflectionShareClient();modal(`<section id="reflection-share"><h2>Share my submitted reflection</h2><p>Preview your reflection before choosing to share. Anyone holding the generated link, including a guardian you send it to, can read it. No message is sent automatically.</p><form id="reflection-share-options" onsubmit="previewReflectionShare(event,${esc(JSON.stringify(projectId))})"><label>Link expires after<select name="days"><option value="7">7 days</option><option value="30">30 days</option><option value="90">90 days</option></select></label><p>Only your name, activity title/programme/type, submitted text, version, submission time and review status will be included. Scores, mentor feedback, files and contacts are excluded.</p><button type="submit">Preview reflection</button><button type="button" onclick="closeModal()">Cancel</button></form></section>`)}
async function previewReflectionShare(event,projectId){event.preventDefault();if(!sharedReady||sharedBusy||uid!==sharedActor)return;const form=event.target,days=Number(new FormData(form).get('days'));if(![7,30,90].includes(days))return;const c={actor:sharedActor,revision:sharedRevision,generation:++reflectionShareGeneration},body={mode:'preview',kind:'REFLECTION',actor:c.actor,revision:c.revision,projectIds:[projectId],purpose:'REFLECTION_SHARING',days,includeHours:false},lock={};reflectionShareDraft=null;reflectionShareLock=lock;lockShared(true);try{const r=await sharedFetch('/api/portfolio-shares',body);if(!reflectionShareCurrent(c)||!$('#modal').open||document.querySelector('#reflection-share-options')!==form)return;const p=r.preview,i=p?.items?.[0];if(p?.kind!=='REFLECTION'||p.audience!=='ANYONE_WITH_LINK'||p.days!==days||p.items.length!==1||typeof i?.reflectionText!=='string'||typeof r.previewDigest!=='string')throw Error('Invalid reflection preview.');modal(`<section id="reflection-share"><h2>Review the reflection you will share</h2><p>${esc(p.studentName)} · Anyone with the link · ${days} days</p><article class="card"><h3>${esc(i.title)}</h3><p>${esc(i.programme)} · ${esc(i.type)}</p><p>${esc(i.status)} · Reflection v${esc(i.reflectionVersion)} · ${esc(eventTime(i.submittedAt))}</p><p style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(i.reflectionText)}</p></article><p>Submission does not imply academic verification. This is separate from official KCC website publication. People with the link may save copies. Revocation stops future access; changes to this source or review status require a fresh preview and link.</p><form id="reflection-share-consent" onsubmit="confirmReflectionShare(event)"><label><input type="checkbox" name="consent" value="yes" required> I consent to share exactly this reflection and displayed fields with anyone holding the link for this duration.</label><button type="submit">Create reflection share link</button><button type="button" onclick="closeModal()">Cancel</button></form></section>`);reflectionShareDraft={c,body:{...body,mode:'create',previewDigest:r.previewDigest},marker:document.querySelector('#reflection-share-consent')};}catch(e){if(reflectionShareCurrent(c))toast(e.message)}finally{if(reflectionShareLock===lock){reflectionShareLock=null;lockShared(false)}}}
async function confirmReflectionShare(event){event.preventDefault();const d=reflectionShareDraft;if(sharedBusy||!d||!reflectionShareCurrent(d.c)||event.target!==d.marker||!$('#modal').open||new FormData(event.target).get('consent')!=='yes')return;const lock={};reflectionShareLock=lock;reflectionShareDraft=null;lockShared(true);try{const r=await sharedFetch('/api/portfolio-shares',{...d.body,consent:true});if(!reflectionShareCurrent(d.c)||!$('#modal').open||document.querySelector('#reflection-share-consent')!==d.marker)return;if(r.actor!==d.c.actor||r.revision!==d.c.revision+1||!r.data||typeof r.url!=='string'||!/^\/share\/[a-f0-9]{64}$/.test(new URL(r.url).pathname)||new URL(r.url).origin!==location.origin)throw Error('Unable to confirm sharing.');applyShared(r);closeModal();modal(`<h2>Reflection share link created</h2><p>Copy this link now and send it to people you choose. It is shown only at creation. No message was sent automatically.</p><label>Reflection share URL<input id="reflection-share-url" readonly value="${esc(r.url)}"></label><button type="button" onclick="copyReflectionShareLink()">Copy reflection link</button><button type="button" onclick="closeModal()">Close</button><p>You can revoke the link through Manage share links beside your reflection or in My Portfolio.</p>`);}catch(e){if(reflectionShareCurrent(d.c)){closeModal();toast('Unable to confirm this link. Refresh and inspect Manage share links before trying again.')}}finally{if(reflectionShareLock===lock){reflectionShareLock=null;lockShared(false)}}}
async function copyReflectionShareLink(){const input=document.querySelector('#reflection-share-url');if(!input)return;try{await navigator.clipboard.writeText(input.value);toast('Reflection link copied.')}catch{input.select();toast('Select and copy the displayed reflection link.')}}
